// ── Loader helper ─────────────────────────────────────────────────────────────

function loadFetchParentContext(mocks) {
    return loadModule(
        'js/fetchParentContextToInput.js',
        makeRequire({
            './common/trackers.js': loadModule('js/common/trackers.js', makeRequire({
                '../config.js': configModule,
