var PARENT_KEY = 'PROJ-100';
var TICKET_KEY = 'PROJ-101';
var INPUT_FOLDER = 'input/PROJ-101';

function makeParams(customParams, overrides) {
    return Object.assign({
        inputFolderPath: INPUT_FOLDER,
        ticket: {
            key: TICKET_KEY,
            fields: {
