        outputs.push({name, calls: JSON.stringify(calls), logs: JSON.stringify(logs)});
    }
    const same = outputs[0].calls === outputs[1].calls && outputs[0].logs === outputs[1].logs;
    console.log(same ? 'IDENTICAL' : 'DIVERGED');
    if (!same) {
        console.log('OLD calls', outputs[0].calls); console.log('NEW calls', outputs[1].calls);
        console.log('OLD logs', outputs[0].logs); console.log('NEW logs', outputs[1].logs);
    }
    return same;
}

